import numpy as np
from scipy.optimize import least_squares
def model(p):
    w,ph,pv,px,a1,a2,a3,a4,a5,a6=p
    return a2 + a1*np.cos(w*t+ph) + a3*np.abs(v)**pv + a4*np.abs(x)**px + a5*t*v + a6*t*v*v
def resid(p):
    r=model(p)-dv_dt
    return np.nan_to_num(r,nan=1e6,posinf=1e6,neginf=-1e6)
best=None
rng=np.random.default_rng(1)
for trial in range(60):
    p0=np.array([rng.uniform(0.2,4),rng.uniform(-3,3),rng.uniform(-2,2),rng.uniform(-2,3),rng.normal(),rng.normal(),rng.normal(),rng.normal(),rng.normal(),rng.normal()])
    try:
        s=least_squares(resid,p0,max_nfev=400)
        nm=np.mean(s.fun**2)/np.var(dv_dt)
        if best is None or nm<best[0]: best=(nm,s.x)
    except Exception as e:
        pass
print("best NMSE", best[0])
print(np.round(best[1],4))
